DO $$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.main_kpi_values(uuid,date)'::regprocedure) INTO body; body:=replace(body,'key text','metric_key text'); body:=replace(body,'key:=','metric_key:='); body:=replace(body,'e.key=key','e.key=metric_key'); body:=replace(body,'||key','||metric_key'); body:=replace(body,'->key','->metric_key'); body:=replace(body,'->>key','->>metric_key'); body:=replace(body,',key)',',metric_key)'); EXECUTE body; END $$;